import java.util.Scanner;
public class JFailCourse1 {
	public static void main(String[] args) {
		//Khutwa 1: Qira madkhalat al-mudarris
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil darajat al-imtihan:");
		int examScore = scan.nextInt();
		System.out.println("Adkhil 'adad al-wajibat al-mufqooda:");
		int numberOfMissingHW = scan.nextInt();		
		scan.close();
		//Khutwa 2: Uktub ta'bir boolean li-tahdid ida kan al-talib yarseb fi al-muqarrar
		boolean isFailing = examScore < 55 || numberOfMissingHW > 2;
		System.out.println(isFailing);
	}
}
